#### 5. 最长回文子串
(https://leetcode.cn/problems/longest-palindromic-substring/)
- 中心拓展法（O(n^2)，不需要额外空间，实际最快）
```cpp
class Solution {
  public:
	string longestPalindrome(string s) {
		if(s.empty())
			return "";
		int maxLength = 1;
		int ansL = 0, ansR = 0;

		auto expand = [&ansL, &ansR, &maxLength, &s](int l, int r) -> void {
			if(r - l == 1 && s[r] == s[l]) {
				if(2 > maxLength) {
					maxLength = 2;
					ansL	  = l;
					ansR	  = r;
				}
			} else if(r - l == 1 && s[r] != s[l]) {
				return;
			}
			while(l > 0 && r < s.size() - 1) {
				l--;
				r++;
				if(s[l] == s[r]) {
					int len = r - l + 1;
					if(len > maxLength) {
						maxLength = len;
						ansL	  = l;
						ansR	  = r;
					}
				} else {
					break;
				}
			}
		};

		for(int i = 0; i < s.size(); i++) {
			expand(i, i);
			if(i + 1 < s.size())
				expand(i, i + 1);
		}
		return s.substr(ansL, ansR - ansL + 1);
	}
};
```
- 回文串一定关于某个中心对称。中心有两种情况
	- 奇数长度：中心是某个字符（如 `aba` 中心是 `b`）
	- 偶数长度：中心是两个字符之间（如 `abba` 中心在 `bb` 中间）
动态规划法（时间复杂度：O(n²)  空间复杂度：O(n²)）
```cpp
string longestPalindromeDP(const string& s) {
    int n = s.size();
    if (n < 2) return s;

    vector<vector<bool>> dp(n, vector<bool>(n, false));
    int start = 0, maxLen = 1;
    for (int i = 0; i < n; ++i) dp[i][i] = true;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            if (s[i] == s[j]) {
                if (len <= 3) dp[i][j] = true;
                else          dp[i][j] = dp[i + 1][j - 1];
            }
            if (dp[i][j] && len > maxLen) {
                maxLen = len;
                start  = i;
            }
        }
    }
    return s.substr(start, maxLen);
}
```
设 `dp[i][j]` 表示 `s[i..j]` 是否为回文
- `s[i] != s[j]` → `dp[i][j] = false`
- `s[i] == s[j]` 且 `j - i <= 2` → `true`（长度 1、2、3）
- 否则 `dp[i][j] = dp[i+1][j-1]`，这里这种情况说明 `s[i] == s[j]`，可以向外拓展了
马拉车算法:
```cpp
int longestPalindromeSubseq(string s) {   // 注意：其实是求子串
    if (s.empty()) return 0;
    int n = s.size(), maxLength = 1;

    auto expand = [&](int l, int r) {
        while (l >= 0 && r < n && s[l] == s[r]) {
            maxLength = max(maxLength, r - l + 1);
            --l; ++r;
        }
    };

    for (int i = 0; i < n; ++i) {
        expand(i, i);            // 奇数中心
        if (i + 1 < n) expand(i, i + 1);  // 偶数中心
    }
    return maxLength;
}
```

